function lichen(ctx,x,y,r,rng,seed,ry){ctx.save();blob(ctx,x,y,r,.18,skRng(seed||3),ry||r);ctx.clip();ctx.fillStyle="rgba(70,36,24,.16)";ctx.fillRect(x-r,y-r,2*r,2*r);ctx.lineWidth=1.3;
  const rr=skRng(seed||3);for(let i=-16;i<16;i++){for(const [dx,k] of [[8,.45],[10,-.8]]){ctx.strokeStyle=`rgba(40,20,14,${.14+rr()*.12})`;ctx.beginPath();const x0=x-r+i*dx;ctx.moveTo(x0,y-r);ctx.bezierCurveTo(x0+r*k*.3+rr()*4,y-r*.3,x0+r*k*.6-rr()*4,y+r*.3,x0+r*k,y+r);ctx.stroke();}}
  ctx.fillStyle="rgba(255,255,255,.06)";for(let i=0;i<60;i++){ctx.beginPath();ctx.arc(x+(rr()-.5)*2*r,y+(rr()-.5)*2*r,2+rr()*3,0,7);ctx.fill();}ctx.restore();}
/* ---------- arrangements ---------- */
function skPlace(L,rng,z=1){
  const {W,H}=SK,n=L.n||1,R=()=>(L.r?L.r[0]+rng()*(L.r[1]-L.r[0]):10)*z,out=[];L=Object.assign({},L,{spread:(L.spread||(L.arr==="groups"?18:30))*Math.sqrt(z),R:(L.R||80)});
  const cx=L.cx??W/2,cy=L.cy??H/2;
  switch(L.arr||"single"){
    case "single":out.push([cx,cy,R()]);break;
    case "scatter":for(let i=0;i<n;i++)out.push([30+rng()*(W-60),24+rng()*(H-60),R()]);break;
    case "group":{const sp=L.spread||30;for(let i=0;i<n;i++){const a=rng()*7,d=Math.sqrt(rng())*sp;out.push([cx+Math.cos(a)*d,cy+Math.sin(a)*d*.8,R()]);}break;}
    case "groups":{const g=L.groups||3;for(let k=0;k<g;k++){const gx=60+rng()*(W-120),gy=50+rng()*(H-110);for(let i=0;i<n;i++){const a=rng()*7,d=Math.sqrt(rng())*(L.spread||18);out.push([gx+Math.cos(a)*d,gy+Math.sin(a)*d,R()]);}}break;}
    case "ring":{const RR=L.R||80;for(let i=0;i<n;i++){const a=i/n*7+rng()*.2;out.push([cx+Math.cos(a)*RR,cy+Math.sin(a)*RR*(L.flat||.8),R()]);}break;}
    case "line":{const x0=L.x0??60,y0=L.y0??H-60,x1=L.x1??W-60,y1=L.y1??60;for(let i=0;i<n;i++){const t=n>1?i/(n-1):.5;out.push([x0+(x1-x0)*t+(rng()-.5)*(L.jit||6),y0+(y1-y0)*t+(rng()-.5)*(L.jit||6),R()]);}break;}
    case "band":{/* dermatomal: groups along a diagonal band */for(let i=0;i<n;i++){const t=rng(),bx=20+t*(W-40),by=H*.75-t*H*.45+(rng()-.5)*50;out.push([bx,by,R()]);}break;}
    case "bandGroups":{const g=L.groups||5;for(let k=0;k<g;k++){const t=(k+.5)/g,gx=30+t*(SK.W-60),gy=SK.H*.72-t*SK.H*.42+(rng()-.5)*30;out.push([gx,gy,0,"G"]);}break;}
    case "xmas":{/* oval lesions along skin cleavage lines (pityriasis rosea) */for(let i=0;i<n;i++){const x=40+rng()*(W-80),y=30+rng()*(H-80);out.push([x,y,R(),x<W/2?-.5:.5]);}break;}
    case "grid":{const c=L.cols||6,rws=Math.ceil(n/c);for(let i=0;i<n;i++)out.push([60+(i%c)*((W-120)/(c-1||1))+(rng()-.5)*14,50+Math.floor(i/c)*((H-110)/(rws-1||1))+(rng()-.5)*14,R()]);break;}
  }
  return out;
}
function skRender(canvas,spec,ti,seed){
  const ratio=Math.min(2,(window.devicePixelRatio||1));canvas.width=SK.W*ratio;canvas.height=SK.H*ratio;
  const ctx=canvas.getContext("2d");ctx.setTransform(1,0,0,1,0,0);
  const rng=skRng((seed||1)*7919+ti*131);
  ctx.setTransform(ratio,0,0,ratio,0,0);skBase(ctx,ti,rng,spec.base||{});
  if(spec.bg)spec.bg.forEach(b=>{const p=PAINT[b.k];if(p)p(ctx,b.x??SK.W/2,b.y??SK.H/2,b.r||160,b,ti,rng);});
  (spec.L||[]).forEach(L=>{const p=PAINT[L.k];if(!p)return;const z=spec.zoom||1;skPlace(L,rng,z).forEach(([x,y,r,rot])=>{
    if(rot==="G"){softFill(ctx,x,y,(L.spread||22)*1.5,skCol("ery",ti),.6,rng,.35,(L.spread||22)*1.1);const m=L.n||10;for(let i=0;i<m;i++){const a=rng()*7,d=Math.sqrt(rng())*(L.spread||22);p(ctx,x+Math.cos(a)*d,y+Math.sin(a)*d*.75,(L.r[0]+rng()*(L.r[1]-L.r[0]))*z,Object.assign({},L,{base:false}),ti,rng);}return;}
    if(rot!=null&&L.k==="plaque"){ctx.save();ctx.translate(x,y);ctx.rotate(rot);p(ctx,0,0,r,Object.assign({},L,{ry:r*.55}),ti,rng);if(L.coll)collarette(ctx,0,0,r,r*.55,rng);ctx.restore();}
    else p(ctx,x,y,r,L,ti,rng);});});
  /* ruler: 1 cm */
  const ink=ti>=3?"rgba(255,255,255,.85)":"rgba(30,26,24,.75)";ctx.strokeStyle=ink;ctx.fillStyle=ink;ctx.lineWidth=1.5;const zz=spec.zoom||1,cmLen=zz>=2.2?SK.CM*zz/2:SK.CM*zz,lab=zz>=2.2?"5 mm":"1 cm",rx=SK.W-16-cmLen,ry=SK.H-14;
  ctx.beginPath();ctx.moveTo(rx,ry);ctx.lineTo(rx+cmLen,ry);ctx.moveTo(rx,ry-4);ctx.lineTo(rx,ry+4);ctx.moveTo(rx+cmLen,ry-4);ctx.lineTo(rx+cmLen,ry+4);ctx.stroke();
  ctx.font="600 11px system-ui,sans-serif";ctx.textAlign="center";ctx.fillText(lab+(zz>1?` · ×${zz}`:""),rx+cmLen/2,ry-6);
}
/* lazy renderer for plates in the DOM: <canvas class="plate" data-spec="id" data-tone="2"> */
const PLATE_SPECS={};
function plateHTML(id,ti,opt={}){return `<canvas class="plate${opt.small?" sm":""}" data-plate="${id}" data-tone="${ti}" width="480" height="320" role="img" aria-label="${esc(opt.label||"Illustrated skin plate")}"></canvas>`;}
function renderPlates(root){
  const draw=c=>{const s=PLATE_SPECS[c.dataset.plate];if(!s){return;}try{skRender(c,s,+c.dataset.tone||0,s.seed||(c.dataset.plate.length*13));c.dataset.done=1;}catch(e){console.warn("plate",c.dataset.plate,e);}};
  const list=$$("canvas.plate:not([data-done])",root);
  if("IntersectionObserver" in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){io.unobserve(e.target);draw(e.target);}}),{rootMargin:"300px"});list.forEach(c=>io.observe(c));}
  else list.forEach(draw);
}

"use strict";
/* ================= TECHNIQUE CLINIC =================
 For examinations you already do but want to be certain of: the proper technique, the reason behind each move,
 the errors that fool you, and drills that rebuild it from several angles (walk-through, order, spot the error,
 narrated run, bedside reps with a checklist, confidence before and after, spaced "why" cards).
 Progress lives in Store.s.notes["tech:<id>"] = {t, conf:[[t,v]...], walk, order, mcq, reps:[{t,n,of,obs}]} (synced, latest wins). */
const TECH_FIG={"otoscopy":"tech-otoscope","direct-ophthalmoscopy":"tech-ophthalmoscope","anterior-rhinoscopy":"tech-rhinoscopy","tinel":"tech-tinel","dix-hallpike":"tech-hallpike","hints":"tech-head-impulse","tendon-reflexes":"tech-reflex","plantar-response":"tech-plantar","tuning-fork":"tech-tuning-fork"};
const TECH_GROUP_IC={"Ear, nose and eye":"eye","Peripheral nerve":"bolt","Sensory":"card","Reflexes and tone":"target","Coordination and gait":"mind","Vestibular and eye movements":"repeat","Meninges and functional":"case"};
const TECH_GROUP_ORDER=["Ear, nose and eye","Peripheral nerve","Sensory","Reflexes and tone","Coordination and gait","Vestibular and eye movements","Meninges and functional"];
const techList=()=>typeof TECH!=="undefined"?TECH:[];
const techById=id=>techList().find(t=>t.id===id);
const techSys=t=>t.group==="Ear, nose and eye"?"hn":"neuro";
function techRec(id){return Store.s.notes["tech:"+id]||{};}
function techSave(id,patch){const r=Object.assign({},techRec(id),patch,{t:Date.now()});Store.s.notes["tech:"+id]=r;Store.save();return r;}
function techConf(id){const c=techRec(id).conf||[];return c.length?c[c.length-1][1]:null;}
function techFirstConf(id){const c=techRec(id).conf||[];return c.length?c[0][1]:null;}
/* five milestones: read it, walked it, ordered it, spotted the errors, three clean bedside reps */
function techMilestones(id){const r=techRec(id),t=techById(id);const clean=(r.reps||[]).filter(x=>x.n>=x.of).length;
  return [["Read",!!r.read],["Walk-through",(r.walk||0)>=0.8],["Order",(r.order||0)>=1],["Errors",t&&(r.mcq||0)>=(t.mcq||[]).length],["3 clean reps",clean>=3]];}
const techDone=id=>techMilestones(id).filter(m=>m[1]).length;
const pips=(id)=>`<span class="mdots" title="${techMilestones(id).map(m=>(m[1]?"✓ ":"· ")+m[0]).join("\n")}">${techMilestones(id).map(m=>`<i class="${m[1]?"on":""}"></i>`).join("")}</span>`;
const CONF_L=["","Unsure","Shaky","Okay","Confident","Certain"];

/* ---------- list ---------- */
function techListView(root){
  const L=techList();const by={};L.forEach(t=>(by[t.group]||(by[t.group]=[])).push(t));
  const mastered=L.filter(t=>techDone(t.id)===5).length,rated=L.filter(t=>techConf(t.id)!=null);
  const gain=rated.filter(t=>(techRec(t.id).conf||[]).length>1).map(t=>techConf(t.id)-techFirstConf(t.id));
  root.innerHTML=`<section class="ph"><span class="eyebrow">Technique clinic</span><h1>Do it right, know why</h1><p class="lede">For the examinations you already do but want to be certain of. Each one breaks down into the proper steps, the reason behind every move, how to tell you got it right, the errors that fool good clinicians and how to rescue a difficult view. Then you rebuild it five ways until it is automatic.</p></section>
   <div class="facts"><div class="fact"><span class="label">Techniques</span><div><b class="mono">${L.length}</b></div></div><div class="fact"><span class="label">Mastered</span><div><b class="mono">${mastered}</b> of ${L.length}</div></div><div class="fact"><span class="label">Confidence gained</span><div><b class="mono">${gain.length?(gain.reduce((a,b)=>a+b,0)>=0?"+":"")+gain.reduce((a,b)=>a+b,0):"–"}</b> ${gain.length?"points":"rate one to start"}</div></div></div>
   <div class="row-x"><button class="btn sm" data-go="practice/techmcq/all">${ic("target")}Spot the error: mixed</button><button class="btn sm ghost" data-go="practice/techorder/random">${ic("shuffle")}Put a random one in order</button></div>
   ${TECH_GROUP_ORDER.filter(g=>by[g]).map(g=>`<section class="section"><span class="label">${esc(g)}</span><div class="list">${by[g].map(t=>{const c=techConf(t.id);return `<button class="lrow" data-go="learn/tech/${t.id}"><span class="icwrap">${ic(TECH_GROUP_IC[g]||"mind")}</span><span class="txt"><b>${esc(t.name)}</b><span>${esc(t.hook||t.purpose)}</span></span><span class="stack" style="gap:4px;align-items:flex-end">${pips(t.id)}${c!=null?`<span class="tiny muted">${CONF_L[c]}</span>`:""}</span></button>`;}).join("")}</div></section>`).join("")}
   ${L.length?"":`<div class="empty">Techniques are being written.</div>`}
   <p class="tiny muted">The five dots: read it · walked it through · put the steps in order · spotted every error · three clean bedside reps. Hold any row for more.</p>`;
}

/* ---------- technique page ---------- */
function techPage(root,id){
  const t=techById(id);if(!t)throw new Error("Technique not found");
  const r=techRec(id);if(!r.read)techSave(id,{read:Date.now()});
  const c=techConf(id),first=techFirstConf(id);
  const figId=TECH_FIG[id];const imgSign=(t.signs||[]).find(s=>IMG_SUBJECTS[s]);
  const n=t.steps.length;
  root.innerHTML=`<section class="ph"><span class="eyebrow">${esc(t.group)} · technique</span><h1>${esc(t.name)}</h1><p class="lede">${esc(t.purpose)}</p>${t.hook?`<p class="quote">${esc(t.hook)}</p>`:""}</section>
   <div class="card stack" style="gap:10px"><div class="row-x"><span class="eyebrow">How sure are you of your technique?</span><span class="spacer"></span>${pips(id)}</div>
    <div class="chips" id="tconf">${[1,2,3,4,5].map(v=>`<button class="chip${c===v?" on":""}" data-c="${v}">${v} · ${CONF_L[v]}</button>`).join("")}</div>
    ${first!=null&&c!=null&&(r.conf||[]).length>1?`<p class="small muted">Started at ${first} (${CONF_L[first]}), now ${c} (${CONF_L[c]}).</p>`:`<p class="small muted">Rate it now, then again after the drills. The change is the point.</p>`}</div>
   <div class="grid">${[
     ["practice/techwalk/"+id,"play","Walk it through","One step at a time: say why before you reveal it."],
     ["practice/techorder/"+id,"shuffle","Put it in order",`${n} steps, shuffled.`],
     ["practice/techmcq/"+id,"target","Spot the error",`${(t.mcq||[]).length} scenarios of technique going wrong.`],
     ["practice/techrep/"+id,"check","Log a bedside rep","Tick each step as you do it on a patient."]
   ].map(([go,i,h,s])=>`<button class="tile" data-go="${go}"><div class="t-top"><span class="icwrap">${ic(i)}</span></div><b>${h}</b><span class="sub">${s}</span></button>`).join("")}</div>
   <div class="row-x"><button class="btn sm soft" id="tnarr">${ic("sounds")}Read it to me</button><button class="btn sm ghost" data-go="learn/techpocket/${id}">${ic("pocket")}Pocket card</button></div>
   ${figId?fig(figId):""}
   ${t.kit&&t.kit.length?`<section class="sec"><h3>Kit</h3><ul class="prose" style="padding-left:1.1em">${t.kit.map(k=>`<li>${esc(k)}</li>`).join("")}</ul></section>`:""}
   ${t.setup&&t.setup.length?`<section class="section"><span class="label">Set up, and why</span><div class="stack" style="gap:8px">${t.setup.map(s=>`<div class="card pad-s stack" style="gap:4px"><b>${esc(s.do)}</b><span class="small"><span class="muted">Why:</span> ${esc(s.why)}</span></div>`).join("")}</div></section>`:""}
   <section class="section"><span class="label">The technique, step by step</span><div class="stack" style="gap:8px">${t.steps.map((s,i)=>`<details class="acc why"${i<2?" open":""}><summary><span class="n">${String(i+1).padStart(2,"0")}</span><span class="st"><b>${esc(s.do)}</b></span></summary><div class="acc-body"><div><span class="k">Why</span>${esc(s.why)}</div>${s.cue?`<div class="note good"><b>You know it's right when</b> ${esc(s.cue)}</div>`:""}</div></details>`).join("")}</div></section>
   ${t.normal?`<section class="sec"><h3>Normal</h3><p>${esc(t.normal)}</p></section>`:""}
   ${t.abnormal&&t.abnormal.length?`<section class="section"><span class="label">What you might find</span><div class="tbl"><table><tr><th>Finding</th><th>Points to</th></tr>${t.abnormal.map(a=>`<tr><td style="font-weight:700">${esc(a.finding)}</td><td>${esc(a.means)}</td></tr>`).join("")}</table></div></section>`:""}
   ${t.errors&&t.errors.length?`<section class="section"><span class="label">Errors that fool good clinicians</span><div class="stack" style="gap:8px">${t.errors.map(e=>`<div class="card pad-s stack" style="gap:6px"><div class="redflag"><b>${esc(e.error)}</b></div><span class="small"><span class="muted">What it does:</span> ${esc(e.result)}</span><span class="small"><span class="muted">Fix:</span> <b>${esc(e.fix)}</b></span></div>`).join("")}</div></section>`:""}
   ${t.trouble&&t.trouble.length?`<section class="section"><span class="label">When it isn't working</span><div class="stack" style="gap:8px">${t.trouble.map(x=>`<details class="acc"><summary><span class="st"><b>“${esc(x.problem)}”</b></span></summary><div class="acc-body"><p>${esc(x.fix)}</p></div></details>`).join("")}</div></section>`:""}
   ${t.pearls&&t.pearls.length?`<section class="card stack hookcard" style="gap:8px"><span class="eyebrow">Pearls</span><ul class="prose" style="padding-left:1.1em">${t.pearls.map(p=>`<li>${esc(p)}</li>`).join("")}</ul></section>`:""}
   ${t.evidence&&t.evidence.length?`<section class="section"><span class="label">The numbers</span><div class="stack" style="gap:6px">${t.evidence.map(e=>`<div class="lm"><b>${esc(e.stat)}</b><span class="tiny muted">${esc(e.src)}</span></div>`).join("")}</div></section>`:""}
   ${t.document?`<section class="sec"><h3>Writing it down</h3><p class="mono small" style="white-space:pre-wrap">${esc(t.document)}</p></section>`:""}
   ${imgSign?`<section class="section"><span class="label">Real examples</span>${Img.galleryHTML("s:"+imgSign,IMG_SUBJECTS[imgSign][1],{title:IMG_SUBJECTS[imgSign][0]})}</section>`:""}
   ${(t.signs||[]).filter(s=>SIGNS[s]).length?`<section class="section"><span class="label">The sign pages this serves</span><div class="chips">${t.signs.filter(s=>SIGNS[s]).map(s=>`<button class="chip" data-go="signs/sign/${s}">${esc(SIGNS[s].name)}</button>`).join("")}</div></section>`:""}
   <p class="tiny muted">Sources: ${(t.src||[]).map(esc).join(" · ")}</p>`;
  $("#tconf").addEventListener("click",e=>{const b=e.target.closest("[data-c]");if(!b)return;const v=+b.dataset.c;const rr=techRec(id);techSave(id,{conf:[...(rr.conf||[]),[Date.now(),v]].slice(-20)});tick(1);toast(`Confidence: ${CONF_L[v]}`,"good");replace("tech",id);});
  $("#tnarr").addEventListener("click",()=>{if(!speechOK()){toast("No speech voice in this browser");return;}
    const q=[`${t.name}.`,...t.steps.map((s,i)=>`Step ${i+1}. ${s.do}. Why: ${s.why}`)];let i=0;const go=()=>{if(i<q.length&&document.body.contains($("#tnarr"))){say(q[i++],go);}};go();toast("Reading the steps aloud. Leave the page to stop.");});
  if(imgSign)Img.bindGalleries(root);
}
route("learn:tech",(id)=>id?(techById(id)||{}).name||"Technique":"Technique clinic",(root,id)=>id?techPage(root,id):techListView(root));

/* ---------- pocket card ---------- */
route("learn:techpocket",(id)=>"Pocket: "+((techById(id)||{}).name||""),(root,id)=>{
  const t=techById(id);if(!t)throw new Error("Technique not found");
  root.innerHTML=`<section class="ph"><span class="eyebrow">Pocket card</span><h1>${esc(t.name)}</h1></section>
   <div class="card stack" style="gap:10px">${t.kit&&t.kit.length?`<p class="small"><b>Kit:</b> ${t.kit.map(esc).join("; ")}</p>`:""}
   <ol class="prose" style="padding-left:1.3em;gap:8px">${[...(t.setup||[]),...t.steps].map(s=>`<li><b>${esc(s.do)}</b></li>`).join("")}</ol>
   ${t.errors&&t.errors.length?`<div class="note bad small"><b>Don't:</b> ${t.errors.slice(0,4).map(e=>esc(e.error)).join(" · ")}</div>`:""}
   ${t.hook?`<p class="quote">${esc(t.hook)}</p>`:""}</div>
   <div class="row-x"><button class="btn sm" data-go="practice/techrep/${id}">${ic("check")}Use it as a checklist now</button><button class="btn sm ghost" onclick="window.print()">Print</button></div>`;
});

/* ---------- walk-through: predict the why ---------- */
route("practice:techwalk",(id)=>"Walk-through",(root,id)=>{
  const t=techById(id);if(!t)throw new Error("Technique not found");
  const S={i:0,known:0,shown:false};const steps=[...(t.setup||[]).map(s=>Object.assign({setup:1},s)),...t.steps];
  const draw=()=>{if(S.i>=steps.length){const pct=S.known/steps.length;const best=Math.max(techRec(id).walk||0,pct);techSave(id,{walk:best});Store.s.xp=(Store.s.xp||0)+Math.round(steps.length/2);tick(2,"hands");
      root.innerHTML=`<section class="ph"><span class="eyebrow">Walk-through · done</span><h1>${S.known} of ${steps.length} reasons recalled</h1><p class="lede">${pct>=.8?"That is the understanding that makes the technique stick. Now do it at the bedside and log the rep.":"The reasons you missed are the ones to read again. They will come back as cards in your sessions."}</p></section>
       <div class="row-x"><button class="btn" data-go="practice/techrep/${id}">${ic("check")}Log a bedside rep</button><button class="btn ghost" data-go="practice/techorder/${id}">${ic("shuffle")}Put it in order</button><button class="btn ghost" data-go="learn/tech/${id}">Back to the technique</button></div>`;return;}
    const s=steps[S.i];
    root.innerHTML=`<div class="progress-top"><button class="iconbtn" data-go="learn/tech/${id}" aria-label="Leave">${ic("close")}</button><div class="meter"><i style="width:${Math.round(S.i/steps.length*100)}%"></i></div><span class="mono small muted">${S.i+1}/${steps.length}</span></div>
     <article class="fc"><div class="row-x"><span class="tag">${s.setup?"Set up":"Step "+(S.i-(t.setup||[]).length+1)}</span><span class="pill">${esc(t.name)}</span></div>
      <div class="q">${esc(s.do)}<small>Why exactly this way? Say the reason out loud, then reveal.</small></div>
      <div id="wa">${S.shown?`<div class="ans"><p><b>Why:</b> ${esc(s.why)}</p>${s.cue?`<div class="note good small"><b>You know it's right when</b> ${esc(s.cue)}</div>`:""}<div class="row-x"><button class="btn soft" data-k="0">I didn't have it</button><button class="btn" data-k="1">I had it</button></div></div>`:`<button class="btn block" id="wr">Reveal the reason</button>`}</div></article>
     <p class="tiny muted" style="text-align:center">Space reveals · 1 missed · 2 had it</p>`;
    const rv=$("#wr");if(rv)rv.addEventListener("click",()=>{S.shown=true;draw();});
    $$("[data-k]",root).forEach(b=>b.addEventListener("click",()=>{S.known+=+b.dataset.k;if(!+b.dataset.k){const cid=`tw:${id}:${S.i}`;if(Store.s.srs[cid]){Store.s.srs[cid].due=Date.now();}}S.i++;S.shown=false;draw();window.scrollTo(0,0);}));
  };
  KEYS.handler=e=>{if(!document.body.contains(root))return;if(e.key===" "&&!S.shown){e.preventDefault();S.shown=true;draw();}else if(S.shown&&(e.key==="1"||e.key==="2")){const b=$(`[data-k="${e.key==="2"?1:0}"]`,root);b&&b.click();}};
  draw();
});

/* ---------- order drill ---------- */
route("practice:techorder",(id)=>"Put it in order",(root,id)=>{
  if(id==="random"||!id){const L=techList();id=L.length?L[Math.floor(Math.random()*L.length)].id:null;}
  const t=techById(id);if(!t)throw new Error("Technique not found");
  const steps=t.steps.map((s,i)=>({i,do:s.do}));let pool=shuf(steps);while(pool.length>2&&pool.every((s,k)=>s.i===k))pool=shuf(steps);
  const S={next:0,miss:0,wrong:null};
  const draw=()=>{const done=S.next>=steps.length;
    root.innerHTML=`<section class="ph"><span class="eyebrow">Put it in order · ${esc(t.group)}</span><h1>${esc(t.name)}</h1><p class="lede">${done?(S.miss?`Done with ${S.miss} misplaced tap${S.miss>1?"s":""}. Run it again until it is clean.`:"Clean run. The sequence is yours."):"Tap the steps in the order you would do them."}</p></section>
     <ol class="stack" style="gap:6px;padding-left:0;list-style:none">${steps.slice(0,S.next).map((s,k)=>`<li class="card pad-s row-x" style="gap:10px"><span class="n mono" style="color:var(--accent-ink)">${String(k+1).padStart(2,"0")}</span><span style="flex:1;min-width:0">${esc(s.do)}</span>${ic("check")}</li>`).join("")}</ol>
     ${done?`<div class="row-x"><button class="btn" id="again">${ic("repeat")}Again</button><button class="btn ghost" data-go="learn/tech/${id}">Back to the technique</button><button class="btn ghost" data-go="practice/techorder/random">Another technique</button></div>`:
     `<div class="opts">${pool.filter(s=>s.i>=S.next).map(s=>`<button class="opt${S.wrong===s.i?" wrong":""}" data-i="${s.i}"><span>${esc(s.do)}</span></button>`).join("")}</div>`}`;
    $$("[data-i]",root).forEach(b=>b.addEventListener("click",()=>{const i=+b.dataset.i;if(i===S.next){S.next++;S.wrong=null;if(S.next>=steps.length){const score=S.miss?Math.max(0,1-S.miss/steps.length):1;techSave(id,{order:Math.max(techRec(id).order||0,score)});Store.s.xp=(Store.s.xp||0)+(S.miss?2:5);tick(1,"hands");}}else{S.miss++;S.wrong=i;const s=t.steps[S.next];toast("Not yet: think about what has to happen first");}draw();}));
    const a=$("#again",root);if(a)a.addEventListener("click",()=>{pool=shuf(steps);S.next=0;S.miss=0;S.wrong=null;draw();});
  };draw();
});

/* ---------- spot the error ---------- */
route("practice:techmcq",(id)=>id==="all"?"Spot the error":"Spot the error",(root,id)=>{
  let Q;if(id==="all"||!id){Q=shuf(techList().flatMap(t=>(t.mcq||[]).map((q,k)=>Object.assign({tid:t.id,tname:t.name,k},q)))).slice(0,10);}
  else{const t=techById(id);if(!t)throw new Error("Technique not found");Q=(t.mcq||[]).map((q,k)=>Object.assign({tid:t.id,tname:t.name,k},q));}
  const S={i:0,right:0,ans:null};
  const draw=()=>{if(S.i>=Q.length){if(id!=="all")techSave(id,{mcq:Math.max(techRec(id).mcq||0,S.right)});Store.s.xp=(Store.s.xp||0)+S.right*2;tick(1,"hands");
      root.innerHTML=`<section class="ph"><span class="eyebrow">Spot the error · done</span><h1>${S.right} of ${Q.length}</h1><p class="lede">${S.right===Q.length?"Every error spotted.":"Read the errors section of the techniques you missed; that is where the fix lives."}</p></section>
       <div class="row-x"><button class="btn" id="again">${ic("repeat")}Again</button>${id!=="all"?`<button class="btn ghost" data-go="learn/tech/${id}">Back to the technique</button>`:`<button class="btn ghost" data-go="learn/tech">All techniques</button>`}</div>`;
      $("#again").addEventListener("click",()=>{S.i=0;S.right=0;S.ans=null;if(id==="all")Q=shuf(Q);draw();});return;}
    const q=Q[S.i];const order=q._o||(q._o=shuf(q.opts.map((_,k)=>k)));
    root.innerHTML=`<div class="progress-top"><button class="iconbtn" data-go="${id==="all"?"learn/tech":"learn/tech/"+id}" aria-label="Leave">${ic("close")}</button><div class="meter"><i style="width:${Math.round(S.i/Q.length*100)}%"></i></div><span class="mono small muted">${S.i+1}/${Q.length}</span></div>
     <article class="fc"><div class="row-x"><span class="tag">Spot the error</span><span class="pill">${esc(q.tname)}</span></div><div class="q" style="font-size:1.12rem">${esc(q.q)}</div>
      <div class="opts">${order.map((k,j)=>`<button class="opt${S.ans!=null?(k===q.a?" right":k===S.ans?" wrong":""):""}" data-k="${k}" ${S.ans!=null?"disabled":""}><span class="kn">${j+1}</span><span>${esc(q.opts[k])}</span></button>`).join("")}</div>
      ${S.ans!=null?`<div class="ans"><div class="verdict-line ${S.ans===q.a?"ok":"no"}">${ic(S.ans===q.a?"check":"close")}${S.ans===q.a?"Right":"Not quite"}</div><p>${esc(q.why)}</p>${id==="all"?`<button class="link small" data-go="learn/tech/${q.tid}" style="align-self:flex-start">Open ${esc(q.tname)}</button>`:""}<button class="btn" id="nx">Continue</button></div>`:""}</article>`;
    $$("[data-k]",root).forEach(b=>b.addEventListener("click",()=>{if(S.ans!=null)return;S.ans=+b.dataset.k;if(S.ans===q.a)S.right++;draw();}));
    const nx=$("#nx",root);if(nx){nx.addEventListener("click",()=>{S.i++;S.ans=null;draw();window.scrollTo(0,0);});nx.focus({preventScroll:true});}
  };
  KEYS.handler=e=>{if(!document.body.contains(root))return;if(/^[1-4]$/.test(e.key)&&S.ans==null){const b=$$(".opt",root)[+e.key-1];b&&b.click();}else if(e.key==="Enter"){const n=$("#nx",root);n&&n.click();}};
  draw();
});

/* ---------- bedside rep with a checklist ---------- */
route("practice:techrep",(id)=>"Bedside rep",(root,id)=>{
  const t=techById(id);if(!t)throw new Error("Technique not found");
  const items=[...(t.setup||[]),...t.steps].map(s=>s.do);const ticked=new Set();let obs=false;
  const draw=()=>{const reps=techRec(id).reps||[];const clean=reps.filter(x=>x.n>=x.of).length;
    root.innerHTML=`<section class="ph"><span class="eyebrow">Bedside rep · ${clean} clean of 3</span><h1>${esc(t.name)}</h1><p class="lede">Do it on a patient, a colleague or yourself. Tick each step as you actually do it, not from memory afterwards. A rep counts as clean when every step is ticked.</p></section>
     <div class="list">${items.map((d,i)=>`<label class="lrow" style="cursor:pointer"><input type="checkbox" data-i="${i}" ${ticked.has(i)?"checked":""} style="width:22px;height:22px;accent-color:var(--accent);flex:none"><span class="txt"><b style="font-weight:${ticked.has(i)?400:700}">${esc(d)}</b></span></label>`).join("")}</div>
     <label class="lrow card" style="cursor:pointer"><input type="checkbox" id="obs" ${obs?"checked":""} style="width:22px;height:22px;accent-color:var(--accent);flex:none"><span class="txt"><b>A colleague watched</b><span>Observed reps are the gold standard for catching habits you can't see yourself.</span></span></label>
     <div class="row-x"><button class="btn" id="save">${ic("check")}Save the rep (${ticked.size}/${items.length})</button><button class="btn ghost" data-go="learn/tech/${id}">Back to the technique</button></div>
     ${reps.length?`<section class="section"><span class="label">Your reps</span><div class="list">${reps.slice().reverse().slice(0,8).map(x=>`<div class="lrow"><span class="dot${x.n>=x.of?" on":""}"></span><span class="txt"><b>${fmtDate(x.t)}</b><span>${x.n}/${x.of} steps${x.obs?" · observed":""}</span></span></div>`).join("")}</div></section>`:""}`;
    $$("input[data-i]",root).forEach(c=>c.addEventListener("change",()=>{const i=+c.dataset.i;c.checked?ticked.add(i):ticked.delete(i);$("#save").innerHTML=`${ic("check")}Save the rep (${ticked.size}/${items.length})`;}));
    $("#obs").addEventListener("change",e=>{obs=e.target.checked;});
    $("#save").addEventListener("click",()=>{const rr=techRec(id);const rep={t:Date.now(),n:ticked.size,of:items.length,obs};techSave(id,{reps:[...(rr.reps||[]),rep].slice(-30)});
      Store.s.xp=(Store.s.xp||0)+(rep.n>=rep.of?6:2);tick(2,"hands");
      const cl=(techRec(id).reps||[]).filter(x=>x.n>=x.of).length;
      toast(rep.n>=rep.of?(cl>=3?"Clean rep. Three clean: this one is yours.":"Clean rep saved"):`Saved: ${rep.of-rep.n} step${rep.of-rep.n>1?"s":""} missed. Those are the habit to fix.`,"good");
      ticked.clear();obs=false;if(techConf(id)!=null&&cl>=3&&techConf(id)<5)setTimeout(()=>toast("Rate your confidence again on the technique page"),2600);draw();window.scrollTo(0,0);});
  };draw();
});

/* ---------- spaced cards: why each step, and the error behind each fix ---------- */
CARD_TYPE_LABEL.twhy="Why this step";CARD_TYPE_LABEL.terr="Technique error";AUTO.terr=1;
(()=>{const orig=cardBody;window.cardBody=function(c){
  if(c.type==="twhy"){const t=techById(c.ref[0]);const s=t.steps[c.ref[1]];
    return {q:`${esc(s.do)}<small>${esc(t.name)}, step ${c.ref[1]+1}. Why is it done exactly this way?</small>`,a:`<p>${esc(s.why)}</p>${s.cue?`<div class="note good small"><b>You know it's right when</b> ${esc(s.cue)}</div>`:""}${TECH_FIG[t.id]&&c.ref[1]<2?fig(TECH_FIG[t.id],{small:true,nocap:true}):""}<button class="link small" data-go="learn/tech/${t.id}" style="align-self:flex-start">Open the technique</button>`};}
  if(c.type==="terr"){const t=techById(c.ref[0]);const q=t.mcq[c.ref[1]];
    return {q:`${esc(q.q)}<small>${esc(t.name)}</small>`,opts:q.opts.map((l,k)=>({l,ok:k===q.a})),explain:`<p class="small">${esc(q.why)}</p><button class="link small" data-go="learn/tech/${t.id}" style="align-self:flex-start">Open the technique</button>`};}
  return orig(c);};})();

/* ---------- technique of the day (for Today) ---------- */
function techOfDay(){const L=techList();if(!L.length)return null;
  const unrated=L.filter(t=>techConf(t.id)==null),weak=L.filter(t=>techConf(t.id)!=null&&techDone(t.id)<5).sort((a,b)=>techConf(a.id)-techConf(b.id));
  const pool=weak.length?weak.slice(0,4):unrated.length?unrated:L;const d=new Date();const seed=d.getFullYear()*400+d.getMonth()*32+d.getDate();return pool[seed%pool.length];}

"use strict";
/* ================= DERMATOLOGY VIEWS ================= */
DCOND.forEach(c=>{if(c.p)PLATE_SPECS["c:"+c.id]=Object.assign({seed:c.id.length*37+c.id.charCodeAt(0)},c.p);});
const DPLATED=()=>DCOND.filter(c=>c.p&&c.d);
DVOCAB.forEach((v,i)=>{if(v[4])PLATE_SPECS["v:"+i]=Object.assign({seed:i*11+5},v[4]);});
DSHAPES.forEach((v,i)=>{if(v[3])PLATE_SPECS["s:"+i]=Object.assign({seed:i*17+3},v[3]);});
const DGROUPS=[...new Set(DCOND.map(c=>c.g))];
const dTone=()=>{const t=Store.s.settings.tone;return t==null?1:t;};
function toneBar(id){return `<div class="tonebar" id="${id}" role="group" aria-label="Skin tone">${TONE_NAME.map((n,i)=>`<button data-tone="${i}" aria-pressed="${dTone()===i}" title="Fitzpatrick ${n}" style="--tc:${rgba(TONES[i])}"><span></span>${n}</button>`).join("")}</div>`;}
function bindTone(root,id,after){const b=$("#"+id,root);if(!b)return;b.addEventListener("click",e=>{const t=e.target.closest("[data-tone]");if(!t)return;Store.s.settings.tone=+t.dataset.tone;Store.save();
  $$("[data-tone]",b).forEach(x=>x.setAttribute("aria-pressed",x===t));$$("canvas.plate.follow",root).forEach(c=>{c.dataset.tone=t.dataset.tone;delete c.dataset.done;});renderPlates(root);after&&after();});}
const fol=(id,opt={})=>plateHTML(id,dTone(),opt).replace('class="plate','class="plate follow');
/* distribution figure: body silhouettes with highlighted regions */
function distMap(key){
  const D=DDIST[key];if(!D)return "";
  let s="";[["f",0],["b",240]].forEach(([v,ox])=>{s+=`<g class="sil">${silhouette(ox)}</g><g class="dreg">`;
    D.R.forEach(([vv,part,box])=>{if(vv!==v)return;
      if(part==="head")s+=`<polygon points="${headBand(box,ox)}"/>`;
      else if(part==="trunk"){if(D.half){const W=BODY.W;s+=`<polygon points="${trunkPoly(box,ox)}" clip-path="url(#halfL${ox})"/>`;}else s+=`<polygon points="${trunkPoly(box,ox)}"/>`;}
      else [false,true].forEach(m=>{s+=`<polygon points="${stripPoly(BODY[part],box,m,ox)}"/>`;});});
    s+=`</g><g class="outl">${silhouette(ox)}</g>`;});
  return `<figure class="fig small dmap"><svg viewBox="0 0 460 470" role="img" aria-label="Distribution: ${esc(D.n)}"><defs><clipPath id="halfL0"><rect x="0" y="0" width="110" height="470"/></clipPath><clipPath id="halfL240"><rect x="350" y="0" width="110" height="470"/></clipPath></defs>${s}
    <text x="110" y="466" text-anchor="middle" class="fl fb">Front</text><text x="350" y="466" text-anchor="middle" class="fl fb">Back</text></svg>
    <figcaption><b>${esc(D.n)}.</b> ${esc(D.d)} <span class="muted">Think: ${esc(D.think)}</span></figcaption></figure>`;
}
const PHOTO_LINKS=c=>[["DermNet",`https://dermnetnz.org/topics/${c.slug}`],["Skin Deep (skin of colour)",`https://dftbskindeep.com/?s=${encodeURIComponent(c.n.split(" (")[0])}`],["Wikimedia Commons",`https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(c.n.split(" (")[0])}&title=Special:MediaSearch&type=image`]];
/* ---------- atlas ---------- */
const DAF={g:"all"};
function dermAtlasHTML(){
  return `${toneBar("atone")}<p class="small muted">Plates are drawn by the app (40 px = 1 cm), not photographs. Switch skin tone to see how each lesion changes on Fitzpatrick types I–VI; each condition links to real photo atlases.</p>
   <div class="chips" id="dag">${[["all","All"],...DGROUPS.map(g=>[g,g])].map(([k,l])=>`<button class="chip${DAF.g===k?" on":""}" data-g="${k}">${l}</button>`).join("")}</div>
   <div class="datlas">${DCOND.filter(c=>DAF.g==="all"||c.g===DAF.g).map(c=>{const pin=Img.pinsOf("d:"+c.id)[0];return `<button class="dtile" data-go="learn/dcond/${c.id}">${c.p?fol("c:"+c.id,{small:true,label:c.n}):pin?`<img class="dtile-ph" loading="lazy" src="${esc(pin.thumb)}" alt="">`:`<div class="dtile-ph ph-txt">${esc(c.n.slice(0,1))}</div>`}<b>${esc(c.n)}</b><span>${esc(c.g)}${c.p?"":" · photos"}</span></button>`;}).join("")}</div>`;
}
function bindAtlas(root,redraw){bindTone(root,"atone");const g=$("#dag",root);if(g)g.addEventListener("click",e=>{const b=e.target.closest("[data-g]");if(!b)return;DAF.g=b.dataset.g;redraw();});renderPlates(root);}
route("learn:datlas","Skin atlas",(root)=>{const draw=()=>{root.innerHTML=`<section class="ph"><span class="eyebrow">Dermatology</span><h1>Skin atlas</h1><p class="lede">${DCOND.length} conditions: ${DPLATED().length} drawn on six skin tones, all with a model description, the features that clinch it, look-alikes, a note on brown and black skin, and live photographs.</p>
  <div class="row-x"><button class="btn sm" data-go="practice/describe">${ic("target")}Describe it (practice)</button><button class="btn sm ghost" data-go="learn/dmorph">Morphology</button><button class="btn sm ghost" data-go="learn/describe">How to describe</button></div></section>${dermAtlasHTML()}`;bindAtlas(root,draw);};draw();});
route("learn:dcond",(id)=>(DCOND.find(c=>c.id===id)||{}).n||"Condition",(root,id)=>{
  const c=DCOND.find(x=>x.id===id);if(!c)throw new Error("Condition not found");
  const d=c.d,row=(k,v)=>v?`<dt>${k}</dt><dd>${esc(Array.isArray(v)?v.join(", "):v)}</dd>`:"";
  root.innerHTML=`<section class="ph"><div class="row-x"><span class="tag">${esc(c.g)}</span><span class="tag">Dermatology</span></div><h1>${esc(c.n)}</h1></section>
   ${c.p?`<div class="card dplate">${fol("c:"+c.id,{label:c.n})}${toneBar("ctone")}</div>`:""}
   ${Img.galleryHTML("d:"+c.id,imgTermsFor(c.id),{title:c.n,links:PHOTO_LINKS(c)})}
   <div class="card stack" style="gap:10px"><span class="eyebrow">Say it like this</span><p class="hook">${esc(c.m)}</p>
    ${d?`<dl class="kv">${row("Primary lesion",d.prim)}${row("Colour",d.col)}${row("Shape",d.shape)}${row("Border",d.border)}${row("Surface",d.surf)}${row("Arrangement",d.arr)}${row("Distribution",DDIST[d.dist]?DDIST[d.dist].n:d.dist)}</dl>`:""}</div>
   <div class="card stack" style="gap:14px"><div class="sec"><h3>Clinches it</h3><ul class="prose" style="padding-left:1.1em">${c.key.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>
    <div class="sec"><h3>Look-alikes</h3><ul class="prose" style="padding-left:1.1em">${c.dd.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>
    <div class="sec"><h3>On brown and black skin</h3><p>${esc(c.soc)}</p></div>
    ${c.act?`<div class="sec"><h3>What to do</h3><p>${esc(c.act)}</p></div>`:""}</div>
   ${d?distMap(d.dist):""}
   ${c.p?`<div class="card stack" style="gap:8px"><span class="eyebrow">Same lesion, six skin tones</span><div class="tonestrip">${[0,1,2,3,4,5].map(t=>`<figure>${plateHTML("c:"+c.id,t,{small:true,label:c.n+" on type "+TONE_NAME[t]})}<figcaption>Type ${TONE_NAME[t]}</figcaption></figure>`).join("")}</div></div>`:""}
   ${memoryBlock("d:"+c.id)}
   <div class="row-x">${c.p&&d?`<button class="btn sm" data-go="practice/describe/${c.id}">${ic("target")}Describe this one</button>`:""}<button class="btn sm ghost" data-go="practice/spot">Spot diagnosis</button></div>`;
  if(c.p)bindTone(root,"ctone");renderPlates(root);Img.bindGalleries(root);
  if(!Store.s.dseen)Store.s.dseen=[];if(!Store.s.dseen.includes(id)){Store.s.dseen.push(id);Store.save();}
});
/* ---------- morphology ---------- */
route("learn:dmorph","Morphology",(root)=>{
  const sec=(title,list)=>`<section class="section"><span class="label">${title}</span><div class="dvocab">${list}</div></section>`;
  root.innerHTML=`<section class="ph"><span class="eyebrow">Dermatology · vocabulary</span><h1>The words of the skin</h1><p class="lede">Learn each term with its picture and its size rule. Most descriptions need only a dozen words used precisely.</p>${toneBar("mtone")}</section>
   ${sec("Primary lesions",DVOCAB.filter(v=>v[1]==="primary").map(v=>vcard(v,DVOCAB.indexOf(v))).join(""))}
   ${sec("Secondary changes",DVOCAB.filter(v=>v[1]==="secondary").map(v=>vcard(v,DVOCAB.indexOf(v))).join(""))}
   ${sec("Shape and arrangement",DSHAPES.map((s,i)=>`<div class="vcard">${s[3]?fol("s:"+i,{small:true,label:s[0]}):""}<b>${esc(s[0])}</b><span>${esc(s[1])}</span><span class="small muted">${esc(s[2])}</span></div>`).join(""))}
   <section class="section"><span class="label">Colour</span><div class="card stack" style="gap:10px">${DCOLOURS.map(([t,d])=>`<div class="lm"><b>${esc(t)}</b><span>${esc(d)}</span></div>`).join("")}</div></section>
   <section class="section"><span class="label">Touch and bedside signs</span><div class="card stack" style="gap:10px">${DPALP.map(([t,d])=>`<div class="lm"><b>${esc(t)}</b><span>${esc(d)}</span></div>`).join("")}</div></section>
   <section class="section"><span class="label">Distribution</span><div class="dists">${Object.keys(DDIST).map(distMap).join("")}</div></section>`;
  bindTone(root,"mtone");renderPlates(root);
});
function vcard(v,i){return `<div class="vcard">${v[4]?fol("v:"+i,{small:true,label:v[0]}):""}<b>${esc(v[0])}</b><span>${esc(v[2])}</span><span class="small muted">${esc(v[3])}</span></div>`;}
/* ---------- describe: framework + builder ---------- */
const DB_OPTS={
 num:["A single","A few","Multiple","Numerous"],size:["1–2 mm","2–5 mm","5–10 mm","1–2 cm","2–5 cm","over 5 cm"],
 shape:["round","oval","polygonal","irregular","annular","targetoid","linear","dome-shaped","umbilicated","drop-like"],
 col:["erythematous","salmon-pink","violaceous","purpuric","hyperpigmented","hypopigmented","depigmented","skin-coloured","pearly","brown","variegated"],
 border:["well-demarcated","ill-defined","irregular","rolled-edged"],
 prim:["macules","patches","papules","plaques","nodules","vesicles","bullae","pustules","wheals","erosions","petechiae"],
 surf:["no surface change","silvery scale","fine scale","greasy scale","a collarette of scale","crust","honey-coloured crust","excoriation","lichenification","telangiectasia","central ulceration","a verrucous surface","central umbilication"],
 site:["extensor elbows and knees","flexures","trunk","face","scalp","hands","lower legs","palms and soles","sun-exposed skin","body folds"],
 arr:["symmetrically","asymmetrically","in groups","in a linear pattern","in a dermatomal band","scattered","coalescing"]
};
const DB={num:"Multiple",size:"2–5 cm",shape:"round",col:"salmon-pink",border:"well-demarcated",prim:"plaques",surf:"silvery scale",site:"extensor elbows and knees",arr:"symmetrically"};
function dbSentence(){const n=DB.num==="A single"?"A single":DB.num;let p=DB.prim;if(n==="A single")p=p.replace(/ae$/,"a").replace(/ches$/,"ch").replace(/s$/,"");
  return `${n} ${DB.border}, ${DB.shape}, ${DB.col} ${p}, ${DB.size}, with ${DB.surf}, ${DB.arr==="scattered"||DB.arr==="coalescing"?DB.arr+" over":"distributed "+DB.arr+" on"} the ${DB.site}.`;}
route("learn:describe","Describe it",(root)=>{
  root.innerHTML=`<section class="ph"><span class="eyebrow">Dermatology · description</span><h1>Describe like a dermatologist</h1><p class="lede">A good description is a diagnosis in waiting. Follow the same order every time and your eye learns to look at each feature.</p></section>
   <div class="stack" style="gap:8px">${DESCRIBE.order.map(([t,d],i)=>`<details class="acc"${i<3?" open":""}><summary><span class="n">${pad2(i+1)}</span><span class="st"><b>${esc(t)}</b><span>${esc(d.split(/[:;.]/)[0])}</span></span></summary><div class="acc-body"><div>${esc(d)}</div></div></details>`).join("")}</div>
   <div class="card stack" style="gap:10px"><span class="eyebrow">The sentence</span><p class="mono small">${esc(DESCRIBE.formula)}</p><p class="hook">${esc(DESCRIBE.example)}</p></div>
   <div class="card stack" style="gap:12px"><span class="eyebrow">Sentence builder</span><p class="small muted">Change any part and read the result aloud.</p>
    <div class="dbgrid">${Object.entries(DB_OPTS).map(([k,o])=>`<label class="dbf"><span>${({num:"Number",size:"Size",shape:"Shape",col:"Colour",border:"Border",prim:"Lesion",surf:"Surface",site:"Site",arr:"Arrangement"})[k]}</span><select id="db-${k}" data-k="${k}">${o.map(x=>`<option${DB[k]===x?" selected":""}>${esc(x)}</option>`).join("")}</select></label>`).join("")}</div>
    <p class="hook" id="dbout">${esc(dbSentence())}</p><div class="row-x"><button class="btn sm ghost" id="dbcopy">Copy</button></div></div>
   <div class="card stack" style="gap:8px"><span class="eyebrow">Tips that make it eloquent</span><ul class="prose" style="padding-left:1.1em">${DESCRIBE.tips.map(t=>`<li>${esc(t)}</li>`).join("")}</ul></div>
   <div class="card stack" style="gap:10px"><span class="eyebrow">Pigmented lesions</span>${DMOLE.map(([t,d])=>`<div class="lm"><b>${esc(t)}</b><span>${esc(d)}</span></div>`).join("")}</div>
   <div class="row-x"><button class="btn" data-go="practice/describe">${ic("target")}Practise on plates</button><button class="btn soft" data-go="learn/demerg">Skin emergencies</button></div>`;
  $$(".dbgrid select",root).forEach(s=>s.addEventListener("change",()=>{DB[s.dataset.k]=s.value;$("#dbout").textContent=dbSentence();}));
  $("#dbcopy").addEventListener("click",()=>{const t=$("#dbout").textContent;try{navigator.clipboard.writeText(t).then(()=>toast("Copied","good"),()=>toast("Select the sentence to copy"));}catch(e){toast("Select the sentence to copy");}});
});
route("learn:demerg","Skin emergencies",(root)=>{
  root.innerHTML=`<section class="ph"><span class="eyebrow">Dermatology · emergencies</span><h1>Skin that can kill</h1><p class="lede">Red flags in any rash: fever and a non-blanching rash, skin pain, blisters with mucosal involvement, erythema over 90% of the skin, pain out of proportion, and a new drug in the past 8 weeks.</p></section>
   ${DEMERG.map(([n,f,a])=>{const c=DCOND.find(x=>n.toLowerCase().includes(x.n.toLowerCase().split(" (")[0].split(" /")[0].slice(0,10)));return `<div class="card stack" style="gap:8px"><b class="h3">${esc(n)}</b><p>${esc(f)}</p><div class="note"><b>Do:</b> ${esc(a)}</div>${c?`<button class="link small" data-go="learn/dcond/${c.id}" style="align-self:flex-start">See the plate</button>`:""}</div>`;}).join("")}`;
});
/* ---------- practice: describe this plate ---------- */
const DCATS=[["prim","Primary lesion"],["col","Colour"],["shape","Shape"],["border","Border"],["surf","Surface"],["arr","Arrangement"],["dist","Distribution"]];
const DPOOL={};DCATS.forEach(([k])=>{DPOOL[k]=[...new Set(DPLATED().flatMap(c=>k==="dist"?[DDIST[c.d.dist].n]:c.d[k]))];});
const DX={q:null,i:0,sel:{},done:false,dx:null,tone:0};
function dxNew(only){const st=Store.s.dprac||{};const P=DPLATED();const order=only?[only]:[...shuf(P.filter(c=>!st[c.id]).map(c=>c.id)),...P.filter(c=>st[c.id]).sort((a,b)=>st[a.id].best-st[b.id].best).map(c=>c.id)].slice(0,6);
  DX.q=order;DX.i=0;dxReset();}
function dxReset(){DX.sel={};DX.done=false;DX.dx=null;DX.tone=Math.floor(Math.random()*6);const c=DCOND.find(x=>x.id===DX.q[DX.i]);DX.opts={};
  DCATS.forEach(([k])=>{const ans=k==="dist"?[DDIST[c.d.dist].n]:c.d[k];const dis=shuf(DPOOL[k].filter(x=>!ans.includes(x))).slice(0,k==="dist"?3:Math.max(3,6-ans.length));DX.opts[k]=shuf([...ans,...dis]);});
  const same=DPLATED().filter(x=>x.id!==c.id&&x.g===c.g),other=DPLATED().filter(x=>x.id!==c.id&&x.g!==c.g);DX.dxopts=shuf([c.id,...shuf(same).slice(0,2).map(x=>x.id),...shuf(other).slice(0,1).map(x=>x.id)]);}
route("practice:describe","Describe it",(root,only)=>{
  if(!Store.s.dprac)Store.s.dprac={};
  if(only||!DX.q)dxNew(only);
  drawDx(root);
});
function drawDx(root){
  root=root||V;const c=DCOND.find(x=>x.id===DX.q[DX.i]);
  const ansOf=k=>k==="dist"?[DDIST[c.d.dist].n]:c.d[k];
  const catHTML=([k,l])=>{const sel=DX.sel[k]||[],ans=ansOf(k);return `<div class="dcat"><span class="k">${l}${k==="dist"?"":" <i>(choose all that fit)</i>"}</span><div class="chips">${DX.opts[k].map(o=>{const on=sel.includes(o);let cls=on?" on":"";if(DX.done){cls=ans.includes(o)?(on?" ok":" miss"):(on?" bad":"");}return `<button class="chip${cls}" data-c="${k}" data-o="${esc(o)}" ${DX.done?"disabled":""}>${esc(o)}</button>`;}).join("")}</div></div>`;};
  let score=0;if(DX.done){DCATS.forEach(([k])=>{const s=DX.sel[k]||[],a=ansOf(k),hit=s.filter(x=>a.includes(x)).length,uni=new Set([...s,...a]).size;score+=uni?hit/uni:0;});score=Math.round(score/DCATS.length*100);}
  root.innerHTML=`<section class="ph"><div class="row-x"><span class="eyebrow">Describe it · ${DX.i+1} of ${DX.q.length}</span><span class="tag">Skin type ${TONE_NAME[DX.tone]}</span></div></section>
   <div class="card dplate">${plateHTML("c:"+c.id,DX.tone,{label:"Describe this plate"})}</div>
   ${distMap(c.d.dist).replace(/<figcaption>[\s\S]*<\/figcaption>/,`<figcaption>Where it is on the body.</figcaption>`)}
   <div class="card stack" style="gap:14px">${DCATS.map(catHTML).join("")}</div>
   <div class="card stack" style="gap:10px"><span class="k">Most likely diagnosis</span><div class="chips">${DX.dxopts.map(id=>{const x=DCOND.find(y=>y.id===id);let cls=DX.dx===id?" on":"";if(DX.done)cls=id===c.id?" ok":(DX.dx===id?" bad":"");return `<button class="chip${cls}" data-dx="${id}" ${DX.done?"disabled":""}>${esc(x.n)}</button>`;}).join("")}</div></div>
   ${DX.done?`<div class="card stack" style="gap:10px"><div class="${score>=70&&DX.dx===c.id?"good":"bad"}-box">Description ${score}% · diagnosis ${DX.dx===c.id?"✓":"✗"}</div><span class="eyebrow">Model description</span><p class="hook">${esc(c.m)}</p><p class="small"><b>${esc(c.n)}.</b> ${esc(c.key[0])}</p>
     <div class="row-x"><button class="btn" id="dxnext">${DX.i+1<DX.q.length?"Next plate":"Finish"}</button><button class="btn ghost sm" data-go="learn/dcond/${c.id}">Open the condition</button></div></div>`
    :`<button class="btn" id="dxcheck">Check my description</button>`}`;
  renderPlates(root);
  if(!DX.done){
    root.querySelectorAll("[data-c]").forEach(b=>b.addEventListener("click",()=>{const k=b.dataset.c,o=b.dataset.o;let s=DX.sel[k]||[];
      if(k==="dist")s=[o];else s=s.includes(o)?s.filter(x=>x!==o):[...s,o];DX.sel[k]=s;const y=window.scrollY;drawDx(root);window.scrollTo(0,y);}));
    root.querySelectorAll("[data-dx]").forEach(b=>b.addEventListener("click",()=>{DX.dx=b.dataset.dx;const y=window.scrollY;drawDx(root);window.scrollTo(0,y);}));
    $("#dxcheck").addEventListener("click",()=>{DX.done=true;const y=window.scrollY;drawDx(root);
      let sc=0;DCATS.forEach(([k])=>{const s=DX.sel[k]||[],a=ansOf(k),hit=s.filter(x=>a.includes(x)).length,uni=new Set([...s,...a]).size;sc+=uni?hit/uni:0;});sc=Math.round(sc/DCATS.length*100)+(DX.dx===c.id?0:-20);
      const r=Store.s.dprac[c.id]||{best:0,n:0};r.n++;r.last=Math.max(0,sc);r.best=Math.max(r.best,r.last);Store.s.dprac[c.id]=r;tick(1,"eye");Store.s.xp=(Store.s.xp||0)+Math.round(Math.max(0,sc)/10);Store.save();window.scrollTo(0,y);});
  }else $("#dxnext").addEventListener("click",()=>{if(DX.i+1<DX.q.length){DX.i++;dxReset();drawDx(root);window.scrollTo(0,0);}else{DX.q=null;toast("Set complete","good");open("practice","describe");}});
}

"use strict";
/* ================= GOOGLE (sign-in, Drive, Calendar) =================
 Same approach as Citrus Maxima and Orange: Google Identity Services token client in the browser, no backend, no secret.
 The access token lives on this device only (localStorage) and lasts an hour; a quiet renewal runs while the Google session is alive. */
const G=(()=>{
  const DEFAULT_CLIENT_ID="753489712404-ra7ahu34gjl305b4ss1765idmqg7am5s.apps.googleusercontent.com"; // the shared "Citrus web" client
  const SCOPES=["https://www.googleapis.com/auth/drive","https://www.googleapis.com/auth/calendar.readonly","https://www.googleapis.com/auth/userinfo.email"].join(" ");
  const TOKEN_KEY="galen.google",IDS_KEY="galen.drive.ids",CFG_KEY="galen.google.cfg";
  let token=null,tokenClient=null,silentInFlight=null,ids={},cfg={clientId:DEFAULT_CLIENT_ID,root:"My Apps"};
  try{token=JSON.parse(localStorage.getItem(TOKEN_KEY)||"null");}catch(e){}
  try{ids=JSON.parse(localStorage.getItem(IDS_KEY)||"{}");}catch(e){}
  try{Object.assign(cfg,JSON.parse(localStorage.getItem(CFG_KEY)||"{}"));}catch(e){}
  const listeners=new Set();const auth={needsSignIn:false,lastError:""};
  const saveToken=t=>{token=t?Object.assign({},token||{},t):null;try{token?localStorage.setItem(TOKEN_KEY,JSON.stringify(token)):localStorage.removeItem(TOKEN_KEY);}catch(e){}listeners.forEach(f=>{try{f(isSignedIn());}catch(e){}});};
  const isSignedIn=()=>!!(token&&token.access_token&&token.exp>Date.now());
  const wasSignedIn=()=>!!(token&&token.email);
  const canUse=()=>window.GALEN_PLATFORM!=="artifact";
  function setConfig(o){Object.assign(cfg,o);try{localStorage.setItem(CFG_KEY,JSON.stringify(cfg));}catch(e){}tokenClient=null;}
  function loadGis(){
    if(window.google&&window.google.accounts&&window.google.accounts.oauth2)return Promise.resolve();
    return new Promise((res,rej)=>{const s=document.createElement("script");s.src="https://accounts.google.com/gsi/client";s.async=true;s.defer=true;s.onload=()=>res();s.onerror=()=>rej(new Error("Google sign-in script did not load (offline?)"));document.head.append(s);});
  }
  async function init(){if(!canUse())throw new Error("Google works in the installed Galen app, not in this preview");await loadGis();tokenClient=window.google.accounts.oauth2.initTokenClient({client_id:cfg.clientId||DEFAULT_CLIENT_ID,scope:SCOPES,prompt:"",callback:()=>{}});}
  function signIn(opt={}){
    const silent=!!opt.silent;if(silent&&silentInFlight)return silentInFlight;
    const p=new Promise(async(res,rej)=>{
      try{if(!tokenClient)await init();}catch(e){return rej(e);}
      const timer=setTimeout(()=>rej(new Error(silent?"silent_timeout":"Sign-in timed out")),silent?15000:120000);
      tokenClient.callback=async(resp)=>{clearTimeout(timer);
        if(resp.error){auth.lastError=resp.error_description||resp.error;return rej(new Error(auth.lastError));}
        saveToken({access_token:resp.access_token,exp:Date.now()+(resp.expires_in-60)*1000});auth.needsSignIn=false;auth.lastError="";
        if(!token.email){try{const u=await userInfo();saveToken({email:u.email||""});}catch(e){}}
        res(token);};
      tokenClient.error_callback=e=>{clearTimeout(timer);rej(new Error(e&&e.type==="popup_closed"?"Sign-in cancelled":(e&&e.type)||"Sign-in failed"));};
      tokenClient.requestAccessToken(Object.assign({prompt:silent?"":"consent"},token&&token.email?{hint:token.email}:{}));
    });
    if(silent){silentInFlight=p.finally(()=>{silentInFlight=null;});return silentInFlight;}
    return p;
  }
  function signOut(){try{if(token&&token.access_token&&window.google&&window.google.accounts)window.google.accounts.oauth2.revoke(token.access_token,()=>{});}catch(e){}saveToken(null);auth.needsSignIn=false;}
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  async function authFetch(url,opts={},attempt=0){
    if(!isSignedIn()){
      if(!wasSignedIn())throw new Error("Not signed in to Google");
      try{await signIn({silent:true});}catch(e){auth.needsSignIn=true;listeners.forEach(f=>{try{f(false);}catch(x){}});const err=new Error("Google sign-in expired — tap Sign in");err.needsSignIn=true;throw err;}
    }
    let r;
    try{r=await fetch(url,Object.assign({},opts,{headers:Object.assign({},opts.headers||{},{Authorization:"Bearer "+token.access_token})}));}
    catch(e){if(attempt<2){await sleep(600*(attempt+1));return authFetch(url,opts,attempt+1);}throw new Error("Network error");}
    if(r.status===401&&attempt<2){saveToken({exp:0});return authFetch(url,opts,attempt+1);}
    if((r.status===429||r.status>=500||r.status===403)&&attempt<3){let rate=r.status!==403;if(r.status===403){try{const j=await r.clone().json();rate=/rate|quota/i.test((j.error&&j.error.message)||"");}catch(e){}}if(rate){await sleep(800*Math.pow(2,attempt));return authFetch(url,opts,attempt+1);}}
    if(!r.ok){let msg=r.status+" "+r.statusText;try{const j=await r.json();msg=(j.error&&j.error.message)||msg;}catch(e){}const e=new Error(msg);e.status=r.status;throw e;}
    if(r.status===204)return null;
    const ct=r.headers.get("content-type")||"";return ct.includes("json")?r.json():r.arrayBuffer();
  }
  const userInfo=()=>authFetch("https://www.googleapis.com/oauth2/v3/userinfo");
  /* ---- Drive ---- */
  const DRIVE="https://www.googleapis.com/drive/v3",UPLOAD="https://www.googleapis.com/upload/drive/v3",FOLDER="application/vnd.google-apps.folder";
  const q=s=>String(s).replace(/\\/g,"\\\\").replace(/'/g,"\\'");
  const remember=(k,id)=>{ids[k]=id;try{localStorage.setItem(IDS_KEY,JSON.stringify(ids));}catch(e){}};
  const forget=pre=>{for(const k of Object.keys(ids))if(k===pre||k.startsWith(pre+"/"))delete ids[k];try{localStorage.setItem(IDS_KEY,JSON.stringify(ids));}catch(e){}};
  async function list(parentId,o={}){const parts=["trashed = false",`'${q(parentId)}' in parents`];if(o.name)parts.push(`name = '${q(o.name)}'`);if(o.folders)parts.push(`mimeType = '${FOLDER}'`);if(o.extra)parts.push(o.extra);
    const j=await authFetch(`${DRIVE}/files?q=${encodeURIComponent(parts.join(" and "))}&fields=files(id,name,mimeType,modifiedTime,size,md5Checksum)&pageSize=200&orderBy=modifiedTime desc`);return j.files||[];}
  async function mkdir(name,parentId){const j=await authFetch(`${DRIVE}/files?fields=id`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name,mimeType:FOLDER,parents:[parentId]})});return j.id;}
  async function ensurePath(parts,o={}){const create=o.create!==false;
    const run=async()=>{let parent="root",key="";for(const name of parts){key=key?key+"/"+name:name;let id=ids[key];if(!id){const found=(await list(parent,{name,folders:true}))[0];if(found)id=found.id;else if(create)id=await mkdir(name,parent);else return null;remember(key,id);}parent=id;}return parent;};
    try{return await run();}catch(e){if(/404|not found/i.test(e.message)){forget(parts[0]);return run();}throw e;}}
  const download=id=>authFetch(`${DRIVE}/files/${id}?alt=media`);
  async function readJsonIn(folderId,name){const f=(await list(folderId,{name}))[0];if(!f)return null;const buf=await download(f.id);try{return {data:JSON.parse(new TextDecoder().decode(buf)),modifiedTime:f.modifiedTime,id:f.id,md5:f.md5Checksum};}catch(e){return null;}}
  async function writeJsonIn(folderId,name,obj,fileId){if(!fileId)fileId=((await list(folderId,{name}))[0]||{}).id||null;
    const boundary="galen"+Date.now();const meta=fileId?{name}:{name,parents:[folderId]};
    const body=`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(meta)}\r\n--${boundary}\r\nContent-Type: application/json\r\n\r\n${JSON.stringify(obj)}\r\n--${boundary}--`;
    const url=fileId?`${UPLOAD}/files/${fileId}?uploadType=multipart&fields=id,modifiedTime,md5Checksum`:`${UPLOAD}/files?uploadType=multipart&fields=id,modifiedTime,md5Checksum`;
    return authFetch(url,{method:fileId?"PATCH":"POST",headers:{"Content-Type":`multipart/related; boundary=${boundary}`},body});}
  async function readJson(parts,name){const id=await ensurePath(parts,{create:false});return id?readJsonIn(id,name):null;}
  async function writeJson(parts,name,obj){const id=await ensurePath(parts);return writeJsonIn(id,name,obj);}
  async function uploadBlob(parts,name,blob,fileId){const folderId=await ensurePath(parts);if(!fileId)fileId=((await list(folderId,{name}))[0]||{}).id||null;
    const meta=fileId?{name}:{name,parents:[folderId]};const fd=new FormData();fd.append("metadata",new Blob([JSON.stringify(meta)],{type:"application/json"}));fd.append("file",blob,name);
    const url=fileId?`${UPLOAD}/files/${fileId}?uploadType=multipart&fields=id,name,size,modifiedTime`:`${UPLOAD}/files?uploadType=multipart&fields=id,name,size,modifiedTime`;
    return authFetch(url,{method:fileId?"PATCH":"POST",body:fd});}
  async function listIn(parts,o){const id=await ensurePath(parts,{create:false});return id?list(id,o):[];}
  async function downloadBlobUrl(fileId){const buf=await download(fileId);return URL.createObjectURL(new Blob([buf]));}
  async function trash(fileId){await authFetch(`${DRIVE}/files/${fileId}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({trashed:true})});}
  /* ---- Calendar (read-only: Citrus writes the blocks) ---- */
  async function listEvents(calendarId,from,to,extra){const p=new URLSearchParams({timeMin:from.toISOString(),timeMax:to.toISOString(),singleEvents:"true",orderBy:"startTime",maxResults:"250"});if(extra)p.set("privateExtendedProperty",extra);
    const j=await authFetch(`https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(calendarId)}/events?${p}`);
    return (j.items||[]).filter(e=>e.status!=="cancelled").map(e=>({id:e.id,title:e.summary||"",start:new Date(e.start.dateTime||e.start.date+"T00:00:00"),end:new Date(e.end.dateTime||e.end.date+"T00:00:00"),allDay:!!e.start.date,description:e.description||"",citrus:(e.extendedProperties&&e.extendedProperties.private&&e.extendedProperties.private.citrus)||""}));}
  return {DEFAULT_CLIENT_ID,cfg,setConfig,auth,canUse,isSignedIn,wasSignedIn,email:()=>(token&&token.email)||"",onAuthChange:f=>{listeners.add(f);return ()=>listeners.delete(f);},signIn,signOut,userInfo,
    ensurePath,readJson,writeJson,readJsonIn,writeJsonIn,uploadBlob,listIn,download,downloadBlobUrl,trash,listEvents,root:()=>cfg.root||"My Apps"};
})();

"use strict";
/* ================= LIVE IMAGE LIBRARY (Wikimedia Commons) =================
 Galen does not ship photographs. It asks Wikimedia Commons for openly licensed photos of each condition or sign,
 keeps only CC0 / public-domain / CC BY / CC BY-SA files, shows the author and licence under each image, and lets you
 pin the best ones (pins sync with your progress) or hide poor ones. Results are cached for 30 days; the service worker keeps the thumbnails. */
const Img=(()=>{
  const API="https://commons.wikimedia.org/w/api.php";
  const CACHE_KEY="galen.imgcache",TTL=30*864e5,MAX=140;
  let cache={};try{cache=JSON.parse(localStorage.getItem(CACHE_KEY)||"{}");}catch(e){}
  const okLicense=l=>/^(cc0|public domain|pd\b|pd-|cc[ -]by(-sa)?(\s*\d(\.\d)?)?$)/i.test((l||"").trim())||/^cc by(-sa)? \d/i.test(l||"");
  const strip=h=>String(h||"").replace(/<[^>]+>/g,"").replace(/\s+/g," ").trim();
  const bad=/histolog|micrograph|microscop|x-ray|radiograph|ct scan|mri|diagram|drawing|illustration|logo|icon|map\b|chart|graph|screenshot|dog|cat\b|horse|cattle|plant|leaf|tree/i;
  function saveCache(){const ks=Object.keys(cache);if(ks.length>MAX){ks.sort((a,b)=>cache[a].t-cache[b].t).slice(0,ks.length-MAX).forEach(k=>delete cache[k]);}try{localStorage.setItem(CACHE_KEY,JSON.stringify(cache));}catch(e){}}
  const canUse=()=>window.GALEN_PLATFORM!=="artifact";
  async function search(term,opt={}){
    const k=term.toLowerCase();const c=cache[k];if(c&&Date.now()-c.t<TTL&&!opt.fresh)return c.items;
    if(!canUse())throw Object.assign(new Error("Live photos work in the installed Galen app"),{preview:true});
    const p=new URLSearchParams({action:"query",format:"json",origin:"*",generator:"search",gsrsearch:`${term} filetype:bitmap -histopathology -histology -micrograph`,gsrnamespace:"6",gsrlimit:"40",prop:"imageinfo",iiprop:"url|extmetadata|size|mime",iiurlwidth:"720",iiextmetadatafilter:"LicenseShortName|Artist|Credit|ImageDescription|LicenseUrl"});
    const r=await fetch(`${API}?${p}`);if(!r.ok)throw new Error("Commons "+r.status);
    const j=await r.json();const pages=Object.values((j.query&&j.query.pages)||{});
    const items=pages.map(pg=>{const ii=(pg.imageinfo||[])[0];if(!ii)return null;const m=ii.extmetadata||{};const lic=strip(m.LicenseShortName&&m.LicenseShortName.value);
      if(!/^image\/(jpeg|png|webp)/.test(ii.mime||"")||!okLicense(lic))return null;
      const title=pg.title.replace(/^File:/,"");if(bad.test(title))return null;
      const desc=strip(m.ImageDescription&&m.ImageDescription.value).slice(0,220);
      return {file:pg.title,title:title.replace(/\.[a-z]+$/i,"").replace(/_/g," "),thumb:ii.thumburl||ii.url,url:ii.url,w:ii.width,h:ii.height,size:ii.size,lic,licUrl:strip(m.LicenseUrl&&m.LicenseUrl.value),author:strip(m.Artist&&m.Artist.value).slice(0,80)||"Unknown author",desc,page:`https://commons.wikimedia.org/wiki/${encodeURIComponent(pg.title)}`};}).filter(Boolean);
    cache[k]={t:Date.now(),items};saveCache();return items;
  }
  async function forSubject(terms,opt={}){
    const seen=new Set(),out=[];let err=null;
    for(const t of terms){try{for(const it of await search(t,opt)){if(seen.has(it.file))continue;seen.add(it.file);out.push(it);}}catch(e){err=e;if(e.preview)break;}}
    if(!out.length&&err)throw err;
    const score=it=>{let s=0;const txt=(it.title+" "+it.desc).toLowerCase();terms.forEach((t,i)=>{if(txt.includes(t.toLowerCase().split(" ")[0]))s+=3-Math.min(i,2);});if(/skin|patient|clinical/i.test(txt))s+=.5;if(it.w>it.h)s+=.2;return s;};
    return out.sort((a,b)=>score(b)-score(a));
  }
  const pinKey=(subject,file)=>subject+"|"+file;
  const pinsOf=subject=>Object.entries(Store.s.pins).filter(([k,v])=>k.startsWith(subject+"|")&&!v.deleted).map(([k,v])=>v).sort((a,b)=>a.t-b.t);
  const isHidden=(subject,file)=>!!(Store.s.hides[pinKey(subject,file)]&&!Store.s.hides[pinKey(subject,file)].deleted);
  function pin(subject,it){Store.s.pins[pinKey(subject,it.file)]=Object.assign({t:Date.now(),subject},it);Store.save();}
  function unpin(subject,file){const k=pinKey(subject,file);if(Store.s.pins[k])Store.s.pins[k]={t:Date.now(),deleted:true,subject,file};Store.save();}
  function hide(subject,file){Store.s.hides[pinKey(subject,file)]={t:Date.now()};Store.save();}
  function unhide(subject,file){const k=pinKey(subject,file);if(Store.s.hides[k])Store.s.hides[k]={t:Date.now(),deleted:true};Store.save();}
  /* ---- UI ---- */
  function galleryHTML(subject,terms,opt={}){
    const pins=pinsOf(subject);
    return `<div class="gal" data-subject="${esc(subject)}" data-terms="${esc(JSON.stringify(terms))}" data-title="${esc(opt.title||terms[0])}">
      <div class="gal-head"><span class="eyebrow">${ic("eye")} Photographs</span><span class="small muted">${pins.length?`${pins.length} pinned`:"from Wikimedia Commons, open licences"}</span></div>
      <div class="gal-grid">${pins.map(p=>thumbHTML(p,true)).join("")}</div>
      <div class="gal-foot"><button class="btn sm soft gal-more">${pins.length?"More photos":"Load photos"}</button>${canUse()&&G.wasSignedIn()?`<label class="btn sm ghost">Add my photo<input type="file" accept="image/*" class="gal-up" hidden></label>`:""}${opt.links?opt.links.map(([t,u])=>`<a class="btn sm ghost" href="${u}" target="_blank" rel="noopener">${esc(t)} ↗</a>`).join(""):""}</div>
      <p class="tiny muted gal-note" hidden></p></div>`;
  }
  const thumbHTML=(it,pinned)=>`<figure class="gal-t${pinned?" pinned":""}" data-file="${esc(it.file)}"><img loading="lazy" src="${esc(it.thumb)}" alt="${esc(it.title)}"><figcaption>${esc(it.lic)}${pinned?" · pinned":""}</figcaption></figure>`;
  function bindGalleries(root){
    $$(".gal",root).forEach(g=>{if(g.dataset.bound)return;g.dataset.bound=1;
      const subject=g.dataset.subject,terms=JSON.parse(g.dataset.terms),grid=$(".gal-grid",g),note=$(".gal-note",g),more=$(".gal-more",g);
      let items=[],loaded=false;
      const draw=()=>{const pins=pinsOf(subject),pf=new Set(pins.map(p=>p.file));
        grid.innerHTML=pins.map(p=>thumbHTML(p,true)).join("")+items.filter(it=>!pf.has(it.file)&&!isHidden(subject,it.file)).slice(0,g.dataset.n||18).map(it=>thumbHTML(it,false)).join("");
        $$(".gal-t",grid).forEach(f=>f.addEventListener("click",()=>{const it=pins.find(p=>p.file===f.dataset.file)||items.find(p=>p.file===f.dataset.file);if(it)lightbox(subject,it,g);}));};
      const load=async()=>{more.disabled=true;more.textContent="Loading…";note.hidden=true;
        try{items=await forSubject(terms);loaded=true;g.dataset.n=18;draw();more.textContent=items.length>18?"Show more":"Search Commons ↗";if(!items.length){note.hidden=false;note.textContent="Nothing suitable found on Commons for this one yet. Try the atlas links.";}}
        catch(e){note.hidden=false;note.textContent=e.preview?"Live photos (with your pins) work in the installed Galen app; here you have the drawn plates and the atlas links.":"Couldn't reach Wikimedia Commons: "+e.message;more.textContent="Retry";}
        more.disabled=false;};
      more.addEventListener("click",()=>{if(!loaded)return load();if(items.length>(+g.dataset.n||18)){g.dataset.n=(+g.dataset.n||18)+18;draw();}else window.open(`https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(terms[0])}&title=Special:MediaSearch&type=image`,"_blank","noopener");});
      const up=$(".gal-up",g);if(up)up.addEventListener("change",async()=>{const f=up.files[0];if(!f)return;more.textContent="Uploading…";try{await Hub.uploadPhoto(f,{subject});toast("Photo saved to your Drive","good");drawOwn();}catch(e){toast("Upload failed: "+e.message,"bad");}more.textContent=loaded?"Show more":"Load photos";});
      const drawOwn=()=>{const own=Object.entries(Store.s.photos).filter(([id,p])=>p.subject===subject&&!p.deleted);if(!own.length)return;let box=$(".gal-own",g);if(!box){box=document.createElement("div");box.className="gal-grid gal-own";grid.after(box);}
        box.innerHTML=own.map(([id,p])=>`<figure class="gal-t own" data-id="${id}"><div class="ph-sk"></div><figcaption>my photo</figcaption></figure>`).join("");
        own.forEach(async([id,p])=>{const f=$(`[data-id="${id}"]`,box);try{const u=await Hub.photoUrl(id);f.innerHTML=`<img src="${u}" alt="${esc(p.caption||p.name)}"><figcaption>my photo</figcaption>`;f.addEventListener("click",()=>lightbox(subject,{file:id,title:p.caption||"My photo",thumb:u,url:u,lic:"Private (your Drive)",author:"You",desc:p.caption||"",own:true},g));}catch(e){f.innerHTML=`<div class="ph-sk"></div><figcaption>offline</figcaption>`;}});};
      draw();drawOwn();
      if(pinsOf(subject).length===0&&canUse()&&"IntersectionObserver" in window&&navigator.onLine!==false){const io=new IntersectionObserver(es=>{if(es.some(e=>e.isIntersecting)){io.disconnect();load();}},{rootMargin:"200px"});io.observe(g);}
    });
  }
  function lightbox(subject,it,g){
    const pinned=!!Store.s.pins[pinKey(subject,it.file)]&&!Store.s.pins[pinKey(subject,it.file)].deleted;
    const big=it.size&&it.size<2.5e6?it.url:(it.thumb||it.url).replace(/\/\d+px-/,"/1280px-");
    const d=document.createElement("div");d.className="lb";d.innerHTML=`<div class="lb-in"><button class="iconbtn lb-x" aria-label="Close">${ic("close")}</button><img src="${esc(big)}" alt="${esc(it.title)}"><div class="lb-meta"><b>${esc(it.title)}</b>${it.desc?`<p class="small">${esc(it.desc)}</p>`:""}<p class="tiny muted">${esc(it.author)} · ${esc(it.lic)}${it.page?` · <a href="${esc(it.page)}" target="_blank" rel="noopener">source</a>`:""}</p>
      <div class="row-x">${it.own?`<button class="btn sm ghost" data-a="del">Delete</button>`:`<button class="btn sm ${pinned?"ghost":""}" data-a="pin">${pinned?"Unpin":"Pin to this page"}</button><button class="btn sm ghost" data-a="hide">Hide</button>`}</div></div></div>`;
    document.body.append(d);document.body.style.overflow="hidden";
    const close=()=>{d.remove();document.body.style.overflow="";};
    d.addEventListener("click",e=>{if(e.target===d||e.target.closest(".lb-x"))close();});
    const esc1=e=>{if(e.key==="Escape"){close();document.removeEventListener("keydown",esc1);}};document.addEventListener("keydown",esc1);
    const re=()=>{close();if(g){delete g.dataset.bound;const html=g.outerHTML;}};
    $$("[data-a]",d).forEach(b=>b.addEventListener("click",async()=>{const a=b.dataset.a;
      if(a==="pin"){pinned?unpin(subject,it.file):pin(subject,it);toast(pinned?"Unpinned":"Pinned","good");}
      else if(a==="hide"){hide(subject,it.file);toast("Hidden from this page");}
      else if(a==="del"){await Hub.deletePhoto(it.file);toast("Deleted");}
      close();if(g){const parent=g.parentNode,subjectT=g.dataset.subject,terms=JSON.parse(g.dataset.terms),title=g.dataset.title;const nu=document.createElement("div");nu.innerHTML=galleryHTML(subjectT,terms,{title});parent.replaceChild(nu.firstElementChild,g);bindGalleries(parent);}
    }));
  }
  /* pool for the spot-diagnosis game: pinned photos first, then cached search results */
  function pool(subject,terms){const pins=pinsOf(subject);if(pins.length)return pins;const out=[];for(const t of terms){const c=cache[t.toLowerCase()];if(c)out.push(...c.items.filter(it=>!isHidden(subject,it.file)));}return out;}
  return {search,forSubject,galleryHTML,bindGalleries,pin,unpin,hide,pinsOf,pool,canUse};
})();

"use strict";
/* ================= THE CITRUS HUB =================
 Galen's own progress lives in <root>/Galen/state.json (merged with this device's copy).
 Galen tells Citrus Maxima where it is through <root>/hub/galen/status.json and reads what Citrus planned (<root>/hub/citrus/plan.json). */
const Hub=(()=>{
  const APP="galen",TITLE="Galen",URL_PAGES="https://galen-app.github.io/galen/";
  const PLAN_KEY="galen.plan",STATUS_KEY="galen.status.fp";
  let stateFileId=null,lastStatusAt=0,lastFp="";
  try{lastFp=localStorage.getItem(STATUS_KEY)||"";}catch(e){}
  const path=()=>[G.root(),"Galen"];
  /* ---- Store provider ---- */
  const provider={name:"drive",label:"Google Drive",
    hint:()=>G.canUse()&&!G.wasSignedIn(),
    needsAction:()=>G.auth.needsSignIn?"Google needs a tap":"Saved on this device",
    async available(){return G.canUse()&&G.wasSignedIn()&&navigator.onLine!==false;},
    async load(){const r=await G.readJson(path(),"state.json");if(r){stateFileId=r.id;return r.data;}return null;},
    async save(s){const r=await G.writeJson(path(),"state.json",s);if(r&&r.id)stateFileId=r.id;writeStatusSoon();}
  };
  Store.register(provider);
  /* ---- week (Fri → Thu, like the other apps) ---- */
  const weekStart=(d=new Date())=>{const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-((x.getDay()-5+7)%7));return x;};
  const addDays=(d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x;};
  const key=d=>dayKey(d.getTime());
  /* ---- what Galen wants today ---- */
  function todayNeed(){
    const due=dueCards().length,room=Math.max(0,Store.s.settings.newPerDay-newToday()),nw=Math.min(room,newCards().length);
    const minutes=clamp(Math.round(due*0.4+nw*0.8)+4,6,45);
    return {due,nw,minutes};
  }
  function hubStatus(){
    const s=Store.s,t=new Date(),need=todayNeed(),ws=weekStart(t),we=addDays(ws,6);
    const days=[];let doneDays=0;for(let i=0;i<7;i++){const d=addDays(ws,i),k=key(d),n=s.days[k]||0;if(n)doneDays++;days.push({date:k,trained:!!n,items:n});}
    const goalDays=5,streakN=streak(),todayDone=(s.days[key(t)]||0)>=10;
    const plan=cachedPlan(),shift=plan&&plan.days&&plan.days[key(t)]&&plan.days[key(t)].shift;
    const pending=[];const unverified=s.log.filter(x=>!x.ver).length;if(unverified)pending.push(`${unverified} bedside finding${unverified>1?"s":""} to verify`);
    const weak=weakCards(3);if(weak.length)pending.push(`Trouble spots: ${weak.map(c=>c.label).slice(0,2).join(", ")}`);
    return {title:TITLE,icon:"🩺",color:"#ee6a1c",app:APP,version:window.GALEN_VERSION||"",device:navigator.platform||"",url:URL_PAGES,updatedAt:new Date().toISOString(),
      summary:`${need.due} due, ${need.nw} new · ${streakN}-day streak`+(todayDone?" · today done":""),
      due:need.due,estimatedMinutes:todayDone?0:need.minutes,streak:streakN,nextDue:todayDone?"tomorrow":"today",
      today:{date:key(t),done:todayDone,items:[{title:"Daily round",minutes:need.minutes,cards:need.due+need.nw}]},
      week:{start:key(ws),end:key(we),done:doneDays,target:goalDays,need:Math.max(0,goalDays-doneDays),days},
      next:{title:"Daily round",minutes:need.minutes},
      asks:todayDone?[]:[{date:null,title:"Galen: daily round",minutes:need.minutes,slot:shift&&shift.overnight?"postnight":"free"}],
      pending,
      extra:{due:need.due,newToday:newToday(),mastery:Math.round(mastery().pct*100),xp:s.xp||0,logUnverified:unverified}};
  }
  let statusTimer=null;
  function writeStatusSoon(){clearTimeout(statusTimer);statusTimer=setTimeout(()=>writeStatus(false),3000);}
  async function writeStatus(force){
    if(!G.canUse()||!G.wasSignedIn()||navigator.onLine===false)return false;
    const st=hubStatus();const fp=JSON.stringify(Object.assign({},st,{updatedAt:0}));
    if(!force&&(fp===lastFp||Date.now()-lastStatusAt<5*60*1000))return false;
    try{await G.writeJson([G.root(),"hub",APP],"status.json",st);lastFp=fp;lastStatusAt=Date.now();try{localStorage.setItem(STATUS_KEY,fp);}catch(e){}
      try{localStorage.setItem("citrus.status."+APP,JSON.stringify(st));}catch(e){} /* same-origin bridge for Citrus */
      return true;}catch(e){console.warn("status.json",e.message);return false;}
  }
  /* ---- Citrus's plan ---- */
  function cachedPlan(){try{return JSON.parse(localStorage.getItem(PLAN_KEY)||"null");}catch(e){return null;}}
  async function readPlan(){
    if(!G.canUse()||!G.wasSignedIn())return cachedPlan();
    try{const r=await G.readJson([G.root(),"hub","citrus"],"plan.json");if(r&&r.data){try{localStorage.setItem(PLAN_KEY,JSON.stringify(r.data));}catch(e){}return r.data;}}catch(e){console.warn("plan.json",e.message);}
    return cachedPlan();
  }
  const mine=b=>b&&((b.app||"").toLowerCase()==="galen"||/galen|exam|bedside|physical/i.test(b.title||""));
  function todayFromPlan(plan){
    plan=plan||cachedPlan();if(!plan||!plan.days)return null;
    const k=key(new Date()),d=plan.days[k];if(!d)return null;
    const y=plan.days[key(addDays(new Date(),-1))];
    return {shift:d.shift||null,afterNight:!!(y&&y.shift&&y.shift.overnight),blocks:(d.blocks||[]).filter(mine),date:k,updatedAt:plan.updatedAt};
  }
  /* ---- own clinical photos (<root>/Galen/photos) ---- */
  async function uploadPhoto(file,meta){
    const name=`${Date.now()}-${(file.name||"photo").replace(/[^\w.\-]+/g,"_")}`;
    const r=await G.uploadBlob([...path(),"photos"],name,file);
    const id=r.id;Store.s.photos[id]={t:Date.now(),name,subject:meta.subject||"",caption:meta.caption||"",size:r.size||file.size};Store.save();return id;
  }
  async function photoUrl(id){return G.downloadBlobUrl(id);}
  async function deletePhoto(id){try{await G.trash(id);}catch(e){}if(Store.s.photos[id]){Store.s.photos[id]={t:Date.now(),deleted:true};Store.save();}}
  /* ---- daily checks: renew quietly, pull, read the plan, write status ---- */
  let lastCheck=0;
  async function daily(reason){
    if(!G.canUse()||!G.wasSignedIn())return;
    if(reason!=="force"&&Date.now()-lastCheck<5*60*1000)return;lastCheck=Date.now();
    await Store.sync();await readPlan();await writeStatus(false);Store.emit("plan");
  }
  return {provider,hubStatus,writeStatus,writeStatusSoon,readPlan,todayFromPlan,todayNeed,cachedPlan,uploadPhoto,photoUrl,deletePhoto,daily,weekStart,URL_PAGES};
})();

